-- Official Navstar catalogue: exactly ten programmes.
-- Archive older/extra courses instead of deleting them so historical enrolments remain valid.
UPDATE courses
SET status = 'archived'
WHERE status = 'active'
  AND id NOT IN (
    'computer-programming','advanced-programming','web-design','graphic-design',
    'robotics-automation','video-editing','html-css','computer-maintenance',
    'integrated-digital-services','python-programming'
  );

